363	  // is its own, and the marker would be a second one for one turn.
364	  if (!d.answersRequest) {
365	    const markerId = postDispatchMarker(d);
366	    const refusal = refuseOutstandingRequest(d, markerId);
367	    if (refusal !== undefined) return refusal;
